import React, { useState, useEffect } from 'react';
import styled from 'styled-components'
import { useTable, usePagination, useSortBy, useFilters, useGroupBy, useExpanded, useRowSelect, } from 'react-table';
import { liquidationsTxJSONLocation } from '../shared/baseUrl';
import { emptyLiquidationTransaction } from '../shared/emptyLiquidationTransaction';
import { greaterThanFunction, includeFilterFunction} from '../services/filters';
import { CellImage, getFontWeight, roundCoinAmount} from '../services/cellDecoration';
import * as helper_functions from '../services/helper_functions';

const Styles = styled.div`

  overflow-x: auto;
  padding: 1rem;

  table {
    border-spacing: 0;
    border: 1px solid black;
    width: 800px;
    table-layout:fixed;

    tr {
      :last-child {
        td {
          border-bottom: 0;
        }
      }
    }

    th,
     
    td {
      margin: 0;
      padding: 0.5rem;
      border-bottom: 1px solid black;
      border-right: 1px solid black;
      overflow: hidden;
      text-overflow: ellipsis;  

      :last-child {
        border-right: 0;
      }
    }

  }

  .pagination {
    padding: 0.5rem;
  }
`

// Be sure to pass our updateMyData and the skipReset option
function Table({ columns, data, liquidatorvalueOutside, borrowervalueOutside, seizetokenOutside, seizeusdvalueOutside}) {

    // Use the state and functions returned from useTable to build your UI
    const {
        getTableProps,
        getTableBodyProps,
        headerGroups,
        prepareRow,
        page, // Instead of using 'rows', we'll use page,
        // which has only the rows for the active page

        // The rest of these things are super handy, too ;)
        canPreviousPage,
        canNextPage,
        pageOptions,
        pageCount,
        gotoPage,
        nextPage,
        previousPage,
        setPageSize,
        setFilter,
        state: {
            pageIndex,
            pageSize
        },
    } = useTable(
        {
            columns,
            data,
        },
        useFilters,
        useGroupBy,
        useSortBy,
        useExpanded,
        usePagination,
        useRowSelect
    )

    // Listen for input changes outside
    useEffect(() => {
        setFilter("liquidator", liquidatorvalueOutside.toLowerCase());
        setFilter("borrower", borrowervalueOutside.toLowerCase());
        setFilter("seize_token", seizetokenOutside.toUpperCase());
        setFilter("seize_usdvalue", seizeusdvalueOutside)
    }, [liquidatorvalueOutside, borrowervalueOutside, seizetokenOutside, seizeusdvalueOutside]);

    // Render the UI for your table
    return (
        <>
            <div className="container">
                <div className="row">
                    <table striped bordered hover size="sm" {...getTableProps()}>
                        <thead>
                            {headerGroups.map(headerGroup => (
                                <tr {...headerGroup.getHeaderGroupProps()}>
                                    {headerGroup.headers.map(column => (
                                        <th {...column.getHeaderProps({
                                            style: { maxWidth: column.maxWidth, width: column.width },
                                        })}>
                                            {column.render("Header")}
                                        </th>
                                    ))}
                                </tr>
                            ))}
                        </thead>
                        <tbody {...getTableBodyProps()}>
                            {page.map(row => {
                                prepareRow(row)
                                return (
                                    <tr {...row.getRowProps()}>
                                        {row.cells.map(cell => {
                                            return (
                                                <td {...cell.getCellProps()}
                                                style={{
                                                    fontWeight : getFontWeight({cell}),
                                                }}                                                
                                                >
                                                    <CellImage cell={cell} />
                                                    {cell.render("Cell")}
                                                </td>
                                            )
                                        })}
                                    </tr>
                                )
                            })}
                        </tbody>
                    </table>
                </div>
            </div>
            {/*Pagination*/}
            <div className="container">
                <div className="row">
                    <div className="col-12 col-sm-3 mt-3">
                        <button type="button" class="btn btn-primary btn-sm" onClick={() => gotoPage(0)} disabled={!canPreviousPage}>
                            {'<<'}
                        </button>{' '}
                        <button type="button" class="btn btn-primary btn-sm" onClick={() => previousPage()} disabled={!canPreviousPage}>
                            {'<'}
                        </button>{' '}
                        <button type="button" class="btn btn-primary btn-sm" onClick={() => nextPage()} disabled={!canNextPage}>
                            {'>'}
                        </button>{' '}
                        <button type="button" class="btn btn-primary btn-sm" onClick={() => gotoPage(pageCount - 1)} disabled={!canNextPage}>
                            {'>>'}
                        </button>{' '}
                        <span>
                            Page{' '}
                            <strong>
                                {pageIndex + 1} of {pageOptions.length}
                            </strong>{' '}
                        </span>
                    </div>
                    <div className='col-6 col-sm-2 me-auto mt-3'>
                        <div class="input-group input-group-sm">
                            <span class="input-group-text" id="inputGroup-sizing-sm">Go to page:</span>
                            <input
                                type="number"
                                defaultValue={pageIndex + 1}
                                onChange={e => {
                                    const page = e.target.value ? Number(e.target.value) - 1 : 0
                                    gotoPage(page)
                                }}
                                class="form-control" aria-label="Sizing example input" aria-describedby="inputGroup-sizing-sm" />
                        </div>
                    </div>
                    <div className='col-6 col-sm-2 me-auto mt-3'>
                        <select class="form-select form-select-sm" aria-label=".form-select-sm example"
                            value={pageSize}
                            onChange={e => {
                                setPageSize(Number(e.target.value))
                            }}
                        >
                            {[10, 20, 30, 40, 50].map(pageSize => (
                                <option key={pageSize} value={pageSize}>
                                    Show {pageSize}
                                </option>
                            ))}
                        </select>
                    </div>
                    <div className="col-5 d-none d-lg-block mt-3"></div>
                </div>
            </div>
        </>
    )
}

function Liquidations() {
    const columns = React.useMemo(
        () => [
            {
                //Header: 'txtime',
                Header: () => (
                    <div
                      style={{
                        textAlign:"center"
                      }}
                    >time</div>),                 
                accessor: 'txtime',
                maxWidth: 140,
            },
            {
                //Header: 'seize $',
                Header: () => (
                    <div
                      style={{
                        textAlign:"center"
                      }}
                    >seize $</div>), 
                accessor: 'seize_usdvalue',
                filter: greaterThanFunction,
                maxWidth: 100,
            },            
            {
                //Header: 'seize token',
                Header: () => (
                    <div
                      style={{
                        textAlign:"center"
                      }}
                    >seize token</div>),                 
                accessor: 'seize_token',
                filter: includeFilterFunction,                
                maxWidth: 95,
            },
            {
                //Header: 'seize amount',
                Header: () => (
                    <div
                      style={{
                        textAlign:"center"
                      }}
                    >seize amount</div>), 
                accessor: 'seize_amount',
                maxWidth: 85,
            },
            {
                //Header: 'repay $',
                Header: () => (
                    <div
                      style={{
                        textAlign:"center"
                      }}
                    >repay $</div>), 
                accessor: 'repay_usdvalue',
                maxWidth: 100,
            },
            {
                //Header: 'repay token',
                Header: () => (
                    <div
                      style={{
                        textAlign:"center"
                      }}
                    >repay token</div>), 
                accessor: 'repay_token',
                maxWidth: 95,
            },            
            {
                //Header: 'repay amount',
                Header: () => (
                    <div
                      style={{
                        textAlign:"center"
                      }}
                    >repay amount</div>), 
                accessor: 'repay_amount',
                maxWidth: 85,
            },
            {
                //Header: 'treasury $',
                Header: () => (
                    <div
                      style={{
                        textAlign:"center"
                      }}
                    >treasury $</div>), 
                accessor: 'treasury_usdvalue',
                maxWidth: 100,
            },
            {
                //Header: 'liquidator',
                Header: () => (
                    <div
                      style={{
                        textAlign:"center"
                      }}
                    >liquidator</div>), 
                accessor: 'liquidator',
                filter: includeFilterFunction,
                Cell: props => <a href={`https://debank.com/profile/${props.value}`} target="_blank">{props.value}</a>,
            },
            {
                //Header: 'borrower',
                Header: () => (
                    <div
                      style={{
                        textAlign:"center"
                      }}
                    >borrower</div>), 
                accessor: 'borrower',
                filter: includeFilterFunction,
                Cell: props => <a href={`https://debank.com/profile/${props.value}`} target="_blank">{props.value}</a>,
            },
            {
                //Header: 'tx',
                Header: () => (
                    <div
                      style={{
                        textAlign:"center"
                      }}
                    >tx</div>), 
                accessor: 'tx',
                maxWidth: 100,
                Cell: props => <a href={`https://bscscan.com/tx/${props.value}`} target="_blank">{props.value}</a>,
            },
        ],

        []
    )

    const [data, setData] = React.useState(emptyLiquidationTransaction);
    const [originalData] = React.useState(data);
    const [liquidatorvalue, setLiquidatorvalue] = useState('');
    const [borrowervalue, setBorrowervalue] = useState('');
    const [seizetoken, setSeizetoken] = useState('');
    const [seizeusdvalue, setSeizeusdvalue] = useState(0);    

    //fill table from whales json-file
    useEffect(() => {
        const fetchData = async () => {
            const liquidationsTxs = await fetch(liquidationsTxJSONLocation)
                .then((response) => response.json());

            liquidationsTxs.sort((a, b) => b.txtime - a.txtime);    

            for (let liquidationTx of liquidationsTxs) {
                liquidationTx.txtime = helper_functions.formatDate(liquidationTx.txtime);
                liquidationTx.seize_usdvalue = Number(liquidationTx.seize_usdvalue.toFixed(2));
                liquidationTx.repay_usdvalue = Number(liquidationTx.repay_usdvalue.toFixed(2));
                liquidationTx.treasury_usdvalue = Number(liquidationTx.treasury_usdvalue.toFixed(2));
                liquidationTx.treasury_amount = roundCoinAmount(liquidationTx.treasury_amount);
                liquidationTx.seize_amount = roundCoinAmount(liquidationTx.seize_amount);
                liquidationTx.repay_amount = roundCoinAmount(liquidationTx.repay_amount);
            }

            setData(liquidationsTxs);
        };

        fetchData();
    }, []);


    // We need to keep the table from resetting the pageIndex when we
    // Update data. So we can keep track of that flag with a ref.
    const skipResetRef = React.useRef(false)

    // When our cell renderer calls updateMyData, we'll use
    // the rowIndex, columnId and new value to update the
    // original data
    const updateMyData = (rowIndex, columnId, value) => {
        // We also turn on the flag to not reset the page
        skipResetRef.current = true
        setData(old =>
            old.map((row, index) => {
                if (index === rowIndex) {
                    return {
                        ...row,
                        [columnId]: value,
                    }
                }
                return row
            })
        )
    }

    // After data changes, we turn the flag back off
    // so that if data actually changes when we're not
    // editing it, the page is reset
    React.useEffect(() => {
        skipResetRef.current = false
    }, [data])

    // Let's add a data resetter/randomizer to help
    // illustrate that flow...
    const resetData = () => {
        // Don't reset the page when we do this
        skipResetRef.current = true
        setData(originalData)
    }

    return (
        <Styles>
            <div className="container">
                <div className='row'>
                    <div className='col-5 col-sm-2 mt-1 mb-2'>
                        <div class="input-group input-group-sm">
                            <span class="input-group-text" id="inputGroup-sizing-sm">liquidator</span>
                            <input
                                type="text"
                                value={liquidatorvalue}
                                onChange={(e) => {
                                    setLiquidatorvalue(e.target.value);
                                }}
                                class="form-control" aria-label="Sizing example input" aria-describedby="inputGroup-sizing-sm" />
                        </div>
                    </div>
                    <div className='col-5 col-sm-2 mt-1 mb-2'>
                        <div class="input-group input-group-sm">
                            <span class="input-group-text" id="inputGroup-sizing-sm">borrower</span>
                            <input
                                type="text"
                                value={borrowervalue}
                                onChange={(e) => {
                                    setBorrowervalue(e.target.value);
                                }}
                                class="form-control" aria-label="Sizing example input" aria-describedby="inputGroup-sizing-sm" />
                        </div>
                    </div>                    
                </div>
                <div className='row'>
                    <div className='col-5 col-sm-2 mt-1 mb-2'>
                        <div class="input-group input-group-sm">
                            <span class="input-group-text" id="inputGroup-sizing-sm">seize token</span>
                            <input
                                type="text"
                                value={seizetoken}
                                onChange={(e) => {
                                    setSeizetoken(e.target.value);
                                }}
                                class="form-control" aria-label="Sizing example input" aria-describedby="inputGroup-sizing-sm" />
                        </div>
                    </div>
                    <div className='col-5 col-sm-2 mt-1 mb-2'>
                        <div class="input-group input-group-sm">
                            <span class="input-group-text" id="inputGroup-sizing-sm">seize $</span>
                            <input
                                type="number"
                                value={seizeusdvalue}
                                onChange={(e) => {
                                    setSeizeusdvalue(e.target.value);
                                }}
                                class="form-control" aria-label="Sizing example input" aria-describedby="inputGroup-sizing-sm" />
                        </div>
                    </div>
                </div>                
            </div>
            <Table
                columns={columns}
                data={data}
                liquidatorvalueOutside={liquidatorvalue}
                borrowervalueOutside={borrowervalue}
                seizetokenOutside={seizetoken}
                seizeusdvalueOutside={seizeusdvalue}
                updateMyData={updateMyData}
                skipReset={skipResetRef.current}
            />
        </Styles >
    )
}

export default Liquidations;